c.python:
class Solution:
    def maxAlternatingValue(self, n: int, s: int, m: int) -> int:
        L = n - 1
        return s + m * ((L + 1) // 2) - L // 2

c.cpp:
class Solution {
public:
    long long maxAlternatingValue(int n, int s, int m) {
        long long L = n - 1;
        return (long long)s + (long long)m * ((L + 1) / 2) - L / 2;
    }
};

